<div x-data="{target:'main'}" class="space-y-6"><div><h1 class="text-3xl font-bold">Certificados Let's Encrypt</h1><p class="text-slate-400">Emisión y renovación para el servidor principal y balanceadores.</p></div><form method="post" action="/certificates" class="bg-slate-900 border border-slate-800 rounded-xl p-5 grid md:grid-cols-4 gap-3"><?=$csrf->field()?><select name="target" x-model="target" class="bg-slate-800 p-2 rounded"><option value="main">Servidor principal</option><option value="balancer">Balanceador</option></select><select name="server_id" x-show="target==='balancer'" class="bg-slate-800 p-2 rounded"><option value="">Seleccionar balanceador</option><?php foreach($servers as $server):?><option value="<?=$server['id']?>"><?=htmlspecialchars($server['name'])?> · <?=htmlspecialchars($server['public_ip']??'sin IP')?></option><?php endforeach?></select><input required name="domain" placeholder="panel.example.com" class="bg-slate-800 p-2 rounded"><input required type="email" name="email" placeholder="admin@example.com" class="bg-slate-800 p-2 rounded"><button class="md:col-span-4 bg-cyan-600 p-2 rounded">Solicitar certificado</button></form><div class="overflow-x-auto border border-slate-800 rounded-xl"><table class="w-full text-sm"><thead class="bg-slate-900"><tr><th class="p-3 text-left">Destino</th><th>Dominio</th><th>Estado</th><th>Expira</th><th>Error</th></tr></thead><tbody class="divide-y divide-slate-800"><?php foreach($requests as $request):?><tr><td class="p-3"><?=htmlspecialchars($request['target_type']==='main'?'Principal':($request['server_name']??'Balanceador'))?></td><td><?=htmlspecialchars($request['domain'])?></td><td class="text-center"><?=htmlspecialchars($request['status'])?></td><td class="text-center"><?=htmlspecialchars($request['expires_at']??'—')?></td><td class="p-3 text-red-400"><?=htmlspecialchars($request['last_error']?substr($request['last_error'],0,160):'')?></td></tr><?php endforeach?></tbody></table></div></div>
